import{a0 as s,I as h,g as d,d as e,k as u,V as c,Y as p,j as _}from"./chunks/framework.Ha9mtr6N.js";const f=JSON.parse('{"title":"Лицензия и конфиденциальность","description":"Пользовательское лицензионное соглашение и Политика конфиденциальности ОмниКрафт ЕРП.","frontmatter":{"title":"Лицензия и конфиденциальность","description":"Пользовательское лицензионное соглашение и Политика конфиденциальности ОмниКрафт ЕРП.","order":20,"eula_version":20260704,"eula_date":"2026-07-04"},"headers":[],"relativePath":"ru/docs/terms.md","filePath":"ru/docs/terms.md"}'),b={name:"ru/docs/terms.md"},g=Object.assign(b,{setup(m){const{frontmatter:t}=s(),o=r=>{if(!r)return"";const[a,l,i]=r.split("-"),n=["января","февраля","марта","апреля","мая","июня","июля","августа","сентября","октября","ноября","декабря"];return`${parseInt(i)} ${n[parseInt(l)-1]} ${a} года`};return(r,a)=>(h(),d("div",null,[a[0]||(a[0]=e("h1",{id:"⚖️-лицензионное-соглашение-и-политика-конфиденциальности",tabindex:"-1"},[u("⚖️ Лицензионное соглашение и Политика конфиденциальности "),e("a",{class:"header-anchor",href:"#⚖️-лицензионное-соглашение-и-политика-конфиденциальности","aria-label":'Permalink to "⚖️ Лицензионное соглашение и Политика конфиденциальности"'},"​")],-1)),e("p",null,[e("em",null,"Действующая редакция от "+c(o(p(t).eula_date)),1)]),a[1]||(a[1]=_('<p>Настоящий документ является официальным предложением (публичной офертой) и представляет собой единое юридическое соглашение между вами (далее — «Пользователь») и Разработчиком (далее — «Лицензиар») об использовании программы для ЭВМ «ОмниКрафт ЕРП» (далее — «Программа») и официального сайта.</p><p>Установка, копирование, загрузка или иное использование Программы означает безоговорочное согласие Пользователя со всеми условиями настоящего документа. Если вы не согласны с условиями, вы обязаны прекратить использование Программы и удалить её со своих устройств.</p><hr><h2 id="часть-1-лицензионное-соглашение-с-конечным-пользователем" tabindex="-1">ЧАСТЬ 1. ЛИЦЕНЗИОННОЕ СОГЛАШЕНИЕ С КОНЕЧНЫМ ПОЛЬЗОВАТЕЛЕМ <a class="header-anchor" href="#часть-1-лицензионное-соглашение-с-конечным-пользователем" aria-label="Permalink to &quot;ЧАСТЬ 1. ЛИЦЕНЗИОННОЕ СОГЛАШЕНИЕ С КОНЕЧНЫМ ПОЛЬЗОВАТЕЛЕМ&quot;">​</a></h2><h3 id="_1-1-предмет-соглашения-и-принцип-работы" tabindex="-1">1.1. Предмет соглашения и принцип работы <a class="header-anchor" href="#_1-1-предмет-соглашения-и-принцип-работы" aria-label="Permalink to &quot;1.1. Предмет соглашения и принцип работы&quot;">​</a></h3><p>Лицензиар предоставляет Пользователю персональное, неисключительное, непередаваемое право использования Программы в соответствии с её функциональным назначением на территории всего мира на весь срок действия исключительного права. Программа разработана на базе архитектуры с приоритетным локальным хранением данных. Это означает, что Программа функционирует автономно на локальном устройстве Пользователя. Все пользовательские данные, включая базы данных, финансовые операции, списки клиентов и номенклатуру, создаются, обрабатываются и хранятся исключительно на локальном жестком диске Пользователя.</p><h3 id="_1-2-типы-лицензии-и-ограничения" tabindex="-1">1.2. Типы лицензий и ограничения <a class="header-anchor" href="#_1-2-типы-лицензии-и-ограничения" aria-label="Permalink to &quot;1.2. Типы лицензий и ограничения&quot;">​</a></h3><p>Программа распространяется по условно-бесплатной модели и предусматривает следующие уровни доступа:</p><ol><li><strong>Ознакомительная версия (Free):</strong> Предоставляется бесплатно без ограничения по времени. Включает полный функционал Программы с техническим ограничением: после проведения 20 (двадцати) операций продаж (чеков) Программа переходит в режим работы «только чтение» в части производственных и торговых операций.</li><li><strong>Коммерческие лицензии (Standard / PRO):</strong> Активируются посредством уникального лицензионного ключа, приобретаемого Пользователем. Снимают ограничения на количество операций и открывают доступ к дополнительным модулям согласно выбранному тарифу.</li></ol><p>Лицензионный ключ технически привязывается к уникальному коду оборудования (идентификатору устройства) Пользователя. Одна коммерческая лицензия может быть привязана не более чем к 5 (пяти) устройствам Пользователя одновременно.</p><h3 id="_1-3-ограничения-использования" tabindex="-1">1.3. Ограничения использования <a class="header-anchor" href="#_1-3-ограничения-использования" aria-label="Permalink to &quot;1.3. Ограничения использования&quot;">​</a></h3><p>Пользователю запрещается:</p><ul><li>Декомпилировать, дизассемблировать, модифицировать или пытаться извлечь исходный код Программы.</li><li>Сдавать Программу в аренду, продавать, сублицензировать или передавать лицензионные ключи активации третьим лицам.</li><li>Использовать Программу для совершения действий, противоречащих действующему законодательству.</li><li>Пытаться обойти технические ограничения ознакомительной версии любым способом.</li></ul><h3 id="_1-4-ограничение-ответственности-и-отказ-от-гарантии" tabindex="-1">1.4. Ограничение ответственности и отказ от гарантий <a class="header-anchor" href="#_1-4-ограничение-ответственности-и-отказ-от-гарантии" aria-label="Permalink to &quot;1.4. Ограничение ответственности и отказ от гарантий&quot;">​</a></h3><p><strong>Программа предоставляется на условиях «как есть». Лицензиар не предоставляет никаких явных или подразумеваемых гарантий того, что Программа будет отвечать требованиям Пользователя, будет работать непрерывно, без сбоев и ошибок.</strong></p><p>ПОЛЬЗОВАТЕЛЬ ПОНИМАЕТ И СОГЛАШАЕТСЯ, ЧТО ЛИЦЕНЗИАР НИ ПРИ КАКИХ ОБСТОЯТЕЛЬСТВАХ НЕ НЕСЕТ ОТВЕТСТВЕННОСТИ ЗА:</p><ol><li>Утерю, искажение или повреждение локальных баз данных Пользователя в результате сбоев питания, поломки жестких дисков, действия вирусов или некорректных действий Пользователя.</li><li>Любые прямые или косвенные убытки, упущенную выгоду или прерывание деловой активности, возникшие в результате использования или невозможности использования Программы.</li></ol><p><strong>Резервное копирование:</strong> Пользователь осознает, что вся ответственность за сохранность коммерческой информации лежит исключительно на нем. Пользователь обязуется самостоятельно и регулярно выполнять резервное копирование своих данных с использованием встроенных инструментов Программы (экспорт в зашифрованные файлы баз данных и архивные папки) на внешние носители или облачные хранилища.</p><h3 id="_1-5-порядок-возврата-средств" tabindex="-1">1.5. Порядок возврата средств <a class="header-anchor" href="#_1-5-порядок-возврата-средств" aria-label="Permalink to &quot;1.5. Порядок возврата средств&quot;">​</a></h3><p>Предоставление Пользователю неисключительного права считается полностью состоявшимся в момент генерации и отправки Пользователю уникального лицензионного ключа активации. Учитывая наличие бесплатной ознакомительной версии, позволяющей всесторонне оценить Программу перед покупкой, возврат денежных средств за приобретенные коммерческие лицензии после передачи ключа не производится (в соответствии со статьей 429.4 Гражданского кодекса Российской Федерации).</p><hr><h2 id="часть-2-политика-конфиденциальности" tabindex="-1">ЧАСТЬ 2. ПОЛИТИКА КОНФИДЕНЦИАЛЬНОСТИ <a class="header-anchor" href="#часть-2-политика-конфиденциальности" aria-label="Permalink to &quot;ЧАСТЬ 2. ПОЛИТИКА КОНФИДЕНЦИАЛЬНОСТИ&quot;">​</a></h2><h3 id="_2-1-отсутствие-сбора-персональных-данных" tabindex="-1">2.1. Отсутствие сбора персональных данных <a class="header-anchor" href="#_2-1-отсутствие-сбора-персональных-данных" aria-label="Permalink to &quot;2.1. Отсутствие сбора персональных данных&quot;">​</a></h3><p>В связи с архитектурой локального хранения данных, Лицензиар не имеет доступа к базам данных Пользователя. Лицензиар не собирает, не обрабатывает и не хранит персональные данные клиентов Пользователя, списки поставщиков, коммерческую тайну, информацию о доходах, остатках на счетах и иную пользовательскую информацию. Лицензиар не является оператором персональных данных (в терминологии Федерального закона № 152-ФЗ «О персональных данных» и европейского регламента по защите данных) применительно к информации, вносимой Пользователем в локальную базу данных Программы.</p><h3 id="_2-2-автоматически-собираемая-техническая-информация-телеметрия" tabindex="-1">2.2. Автоматически собираемая техническая информация (Телеметрия) <a class="header-anchor" href="#_2-2-автоматически-собираемая-техническая-информация-телеметрия" aria-label="Permalink to &quot;2.2. Автоматически собираемая техническая информация (Телеметрия)&quot;">​</a></h3><p>Для обеспечения работы системы лицензирования и улучшения качества Программы, Лицензиар может собирать исключительно обезличенную техническую информацию:</p><ul><li><strong>Уникальный код оборудования (идентификатор устройства):</strong> Обезличенный криптографический хэш параметров оборудования. Он используется исключительно для проверки привязки лицензионного ключа и защиты от пиратства. Данный код не позволяет идентифицировать конкретное физическое лицо.</li><li><strong>Технические метрики:</strong> Язык интерфейса, версия операционной системы, версия Программы и счетчик проведенных операций (для контроля лимита бесплатной версии).</li><li><strong>Отчеты о сбоях:</strong> В случае критической ошибки Программа отправляет технический отчет о последовательности вызовов (трассировку стека). Программа автоматически вырезает персональные пути локальных папок компьютера, заменяя их на обезличенные маски, чтобы исключить передачу имени учетной записи операционной системы.</li></ul><p>В случае, если какая-либо часть автоматически собираемой технической информации (например, сетевой адрес устройства или код оборудования) будет признана персональными данными согласно применимому законодательству, Лицензиар осуществляет их обработку исключительно в целях исполнения настоящего Соглашения (на основании пункта 5 части 1 статьи 6 Федерального закона № 152-ФЗ «О персональных данных»).</p><h3 id="_2-3-управление-согласием-отказ-от-сбора" tabindex="-1">2.3. Управление согласием (Отказ от сбора) <a class="header-anchor" href="#_2-3-управление-согласием-отказ-от-сбора" aria-label="Permalink to &quot;2.3. Управление согласием (Отказ от сбора)&quot;">​</a></h3><p>Пользователь имеет полное право в любой момент отозвать свое согласие на передачу аналитической информации и отчетов об ошибках. Для этого достаточно снять соответствующую отметку в разделе «Настройки программы» (Глобальные настройки). При отключении данного параметра Программа переходит в полностью автономный режим (за исключением разовых запросов к серверу при ручной активации лицензионного ключа).</p><h3 id="_2-4-использование-официального-саита" tabindex="-1">2.4. Использование официального сайта <a class="header-anchor" href="#_2-4-использование-официального-саита" aria-label="Permalink to &quot;2.4. Использование официального сайта&quot;">​</a></h3><p>При посещении сайта <code>omnicraft-erp.com</code> веб-сервер может автоматически собирать стандартные журналы подключений (сетевой адрес устройства, тип браузера, время доступа) исключительно в целях обеспечения сетевой безопасности и защиты от сетевых атак на отказ в обслуживании. Сайт не использует рекламные или отслеживающие сторонние файлы «куки».</p><hr><h2 id="часть-3-заключительные-положения-и-реквизиты" tabindex="-1">ЧАСТЬ 3. ЗАКЛЮЧИТЕЛЬНЫЕ ПОЛОЖЕНИЯ И РЕКВИЗИТЫ <a class="header-anchor" href="#часть-3-заключительные-положения-и-реквизиты" aria-label="Permalink to &quot;ЧАСТЬ 3. ЗАКЛЮЧИТЕЛЬНЫЕ ПОЛОЖЕНИЯ И РЕКВИЗИТЫ&quot;">​</a></h2><h3 id="_3-1-применимое-право-и-разрешение-споров" tabindex="-1">3.1. Применимое право и разрешение споров <a class="header-anchor" href="#_3-1-применимое-право-и-разрешение-споров" aria-label="Permalink to &quot;3.1. Применимое право и разрешение споров&quot;">​</a></h3><p>Настоящее Соглашение регулируется и толкуется в соответствии с действующим законодательством Российской Федерации. Все споры и разногласия, возникающие в связи с настоящим Соглашением, подлежат обязательному досудебному претензионному урегулированию. Срок рассмотрения письменной претензии составляет 30 (тридцать) календарных дней с момента ее получения. При невозможности урегулирования спора в досудебном порядке, он подлежит рассмотрению в суде по месту нахождения Лицензиара.</p><h3 id="_3-2-обстоятельства-непреодолимои-силы-форс-мажор" tabindex="-1">3.2. Обстоятельства непреодолимой силы (Форс-мажор) <a class="header-anchor" href="#_3-2-обстоятельства-непреодолимои-силы-форс-мажор" aria-label="Permalink to &quot;3.2. Обстоятельства непреодолимой силы (Форс-мажор)&quot;">​</a></h3><p>Стороны освобождаются от ответственности за частичное или полное неисполнение обязательств по настоящему Соглашению, если оно явилось следствием обстоятельств непреодолимой силы. К таким обстоятельствам относятся чрезвычайные и непредотвратимые события, включая военные действия, стихийные бедствия, решения государственных органов, масштабные аварии в работе сети Интернет, сбои серверов или облачных провайдеров, а также тяжелая внезапная болезнь либо экстренная госпитализация Лицензиара, объективно препятствующая исполнению обязательств в установленный срок. Срок исполнения обязательств по Соглашению продлевается соразмерно времени, в течение которого действовали такие обстоятельства.</p><h3 id="_3-3-изменение-условии" tabindex="-1">3.3. Изменение условий <a class="header-anchor" href="#_3-3-изменение-условии" aria-label="Permalink to &quot;3.3. Изменение условий&quot;">​</a></h3><p>Лицензиар оставляет за собой право в одностороннем порядке вносить изменения в настоящее Соглашение. Новая редакция вступает в силу с момента ее публикации на официальном сайте Программы. В случае несогласия Пользователя с изменениями Соглашения, Пользователь обязан незамедлительно прекратить любое использование Программы и удалить её со своих устройств. Продолжение использования Программы после изменения условий означает согласие Пользователя с новой редакцией Соглашения.</p><h3 id="_3-4-язык-соглашения" tabindex="-1">3.4. Язык Соглашения <a class="header-anchor" href="#_3-4-язык-соглашения" aria-label="Permalink to &quot;3.4. Язык Соглашения&quot;">​</a></h3><p>Настоящее Соглашение может быть переведено на другие языки для удобства Пользователей. В случае любых разночтений, расхождений или противоречий между версией Соглашения на русском языке и версией на любом другом языке, преимущественную (превалирующую) и окончательную юридическую силу всегда имеет версия на русском языке.</p><h3 id="_3-5-реквизиты-разработчика-лицензиара" tabindex="-1">3.5. Реквизиты Разработчика (Лицензиара) <a class="header-anchor" href="#_3-5-реквизиты-разработчика-лицензиара" aria-label="Permalink to &quot;3.5. Реквизиты Разработчика (Лицензиара)&quot;">​</a></h3><p>Правообладателем и Разработчиком Программы является: <strong>Физическое лицо Мурашкин Николай Валерьевич</strong>, применяющее специальный налоговый режим «Налог на профессиональный доход» (самозанятый). Подробная информация о разработчике, его мастерской и философии проекта доступна в разделе <a href="/ru/docs/about">О разработчиках</a>.</p><ul><li><strong>ИНН:</strong> 232904256501</li><li><strong>Контакты для официальных обращений:</strong> Первичное направление юридически значимых сообщений, запросов, досудебных претензий и вопросов по лицензированию осуществляется исключительно через официальную форму связи на сайте мастерской разработчика: <strong><a href="https://nmurashkin.ru/contacts" target="_blank" rel="noreferrer">https://nmurashkin.ru/contacts</a></strong>. После получения первоначального обращения дальнейшая переписка и обмен документами могут вестись по электронной почте с использованием адресов, с которых отправляются ответы Лицензиара.</li></ul>',45))]))}});export{f as __pageData,g as default};
